import { Router } from 'express';
import prisma from '../lib/prisma.js';
import { authenticate, authorize } from '../middleware/auth.js';

const router = Router();

router.use(authenticate);

function resolveMagasinId(req) {
  if (req.user.role === 'MAGASIN') {
    return req.user.magasinId;
  }
  return req.query.magasinId || req.body.magasinId;
}

router.get('/', async (req, res) => {
  const magasinId = resolveMagasinId(req);

  if (!magasinId) {
    return res.status(400).json({ error: 'Magasin requis' });
  }

  if (req.user.role === 'MAGASIN' && req.user.magasinId !== magasinId) {
    return res.status(403).json({ error: 'Accès non autorisé' });
  }

  const inventaires = await prisma.inventaireMagasin.findMany({
    where: { magasinId },
    include: { produit: true },
    orderBy: { produit: { nom: 'asc' } },
  });

  res.json(inventaires);
});

router.put('/:produitId', authorize('ADMIN', 'MAGASIN'), async (req, res) => {
  const magasinId = resolveMagasinId(req);
  const { quantite, seuilAlerte } = req.body;

  if (!magasinId) {
    return res.status(400).json({ error: 'Magasin requis' });
  }

  if (req.user.role === 'MAGASIN' && req.user.magasinId !== magasinId) {
    return res.status(403).json({ error: 'Accès non autorisé' });
  }

  const inventaire = await prisma.inventaireMagasin.upsert({
    where: {
      magasinId_produitId: {
        magasinId,
        produitId: req.params.produitId,
      },
    },
    update: {
      ...(quantite != null && { quantite }),
      ...(seuilAlerte != null && { seuilAlerte }),
    },
    create: {
      magasinId,
      produitId: req.params.produitId,
      quantite: quantite ?? 0,
      seuilAlerte: seuilAlerte ?? 5,
    },
    include: { produit: true },
  });

  res.json(inventaire);
});

router.post('/initialiser', authorize('ADMIN'), async (req, res) => {
  const { magasinId } = req.body;

  if (!magasinId) {
    return res.status(400).json({ error: 'Magasin requis' });
  }

  const produits = await prisma.produit.findMany({ where: { actif: true } });

  for (const produit of produits) {
    await prisma.inventaireMagasin.upsert({
      where: {
        magasinId_produitId: { magasinId, produitId: produit.id },
      },
      update: {},
      create: { magasinId, produitId: produit.id, quantite: 0 },
    });
  }

  const inventaires = await prisma.inventaireMagasin.findMany({
    where: { magasinId },
    include: { produit: true },
  });

  res.json(inventaires);
});

export default router;

import { Router } from 'express';
import prisma from '../lib/prisma.js';
import { authenticate, authorize } from '../middleware/auth.js';

const router = Router();

router.use(authenticate);

async function generateNumeroCommande() {
  const count = await prisma.commande.count();
  return `CMD-${new Date().getFullYear()}-${String(count + 1).padStart(4, '0')}`;
}

router.get('/', async (req, res) => {
  const where = {};

  if (req.user.role === 'MAGASIN') {
    where.magasinId = req.user.magasinId;
  } else if (req.query.magasinId) {
    where.magasinId = req.query.magasinId;
  }

  if (req.query.statut) {
    where.statut = req.query.statut;
  }

  const commandes = await prisma.commande.findMany({
    where,
    include: {
      magasin: true,
      lignes: { include: { produit: true } },
    },
    orderBy: { createdAt: 'desc' },
  });

  res.json(commandes);
});

router.get('/:id', async (req, res) => {
  const commande = await prisma.commande.findUnique({
    where: { id: req.params.id },
    include: {
      magasin: true,
      lignes: { include: { produit: true } },
    },
  });

  if (!commande) {
    return res.status(404).json({ error: 'Commande introuvable' });
  }

  if (req.user.role === 'MAGASIN' && req.user.magasinId !== commande.magasinId) {
    return res.status(403).json({ error: 'Accès non autorisé' });
  }

  res.json(commande);
});

router.post('/', authorize('MAGASIN', 'ADMIN'), async (req, res) => {
  const magasinId = req.user.role === 'MAGASIN' ? req.user.magasinId : req.body.magasinId;
  const { lignes, notes } = req.body;

  if (!magasinId || !lignes?.length) {
    return res.status(400).json({ error: 'Magasin et lignes de commande requis' });
  }

  const numero = await generateNumeroCommande();

  const commande = await prisma.commande.create({
    data: {
      numero,
      magasinId,
      notes,
      lignes: {
        create: lignes.map((ligne) => ({
          produitId: ligne.produitId,
          quantite: ligne.quantite,
        })),
      },
    },
    include: {
      magasin: true,
      lignes: { include: { produit: true } },
    },
  });

  res.status(201).json(commande);
});

router.patch('/:id/statut', authorize('PRODUCTION', 'ADMIN'), async (req, res) => {
  const { statut } = req.body;
  const validStatuts = ['EN_ATTENTE', 'EN_PREPARATION', 'EXPEDIEE', 'LIVREE', 'ANNULEE'];

  if (!validStatuts.includes(statut)) {
    return res.status(400).json({ error: 'Statut invalide' });
  }

  const commande = await prisma.commande.update({
    where: { id: req.params.id },
    data: { statut },
    include: {
      magasin: true,
      lignes: { include: { produit: true } },
    },
  });

  if (statut === 'LIVREE') {
    for (const ligne of commande.lignes) {
      await prisma.inventaireMagasin.upsert({
        where: {
          magasinId_produitId: {
            magasinId: commande.magasinId,
            produitId: ligne.produitId,
          },
        },
        update: { quantite: { increment: ligne.quantite } },
        create: {
          magasinId: commande.magasinId,
          produitId: ligne.produitId,
          quantite: ligne.quantite,
        },
      });

      await prisma.stockProductionProduit.update({
        where: { produitId: ligne.produitId },
        data: { quantite: { decrement: ligne.quantite } },
      });
    }
  }

  res.json(commande);
});

export default router;

