import { FormEvent, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export function LoginPage() {
  const { user, login } = useAuth();
  const [email, setEmail] = useState('centre@delice.fr');
  const [password, setPassword] = useState('demo123');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  if (user) {
    return <Navigate to="/" replace />;
  }

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setError('');
    setLoading(true);

    try {
      await login(email, password);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Connexion impossible');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="login-header">
          <span className="brand-icon large">🥖</span>
          <h1>Le Temps d'un Délice</h1>
          <p>Plateforme de gestion pour magasins et centre de production</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <label>
            Email
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </label>

          <label>
            Mot de passe
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </label>

          {error && <p className="error-text">{error}</p>}

          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Connexion...' : 'Se connecter'}
          </button>
        </form>

        <div className="demo-accounts">
          <p>Comptes de démonstration (mot de passe : demo123)</p>
          <ul>
            <li><strong>admin@delice.fr</strong> — Administrateur</li>
            <li><strong>centre@delice.fr</strong> — Magasin Centre-Ville</li>
            <li><strong>nord@delice.fr</strong> — Magasin Quartier Nord</li>
            <li><strong>production@delice.fr</strong> — Centre de production</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

