import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { commandesApi, dashboardApi } from '../lib/api';
import { PageHeader, StatCard, StatusBadge } from '../components/UI';
import type { Commande, DashboardData } from '../types';

export function DashboardPage() {
  const { user } = useAuth();
  const [dashboard, setDashboard] = useState<DashboardData | null>(null);
  const [mesCommandes, setMesCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    async function load() {
      try {
        if (user?.role === 'MAGASIN') {
          const commandes = await commandesApi.list();
          setMesCommandes(commandes.slice(0, 5));
        } else {
          const data = await dashboardApi.get();
          setDashboard(data);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Erreur de chargement');
      }
    }

    load();
  }, [user]);

  if (user?.role === 'MAGASIN') {
    return (
      <>
        <PageHeader
          title={`Bonjour, ${user.nom}`}
          subtitle={user.magasin ? `Magasin : ${user.magasin.nom}` : undefined}
          action={
            <Link to="/nouvelle-commande" className="btn btn-primary">
              Nouvelle commande
            </Link>
          }
        />

        {error && <p className="error-text">{error}</p>}

        <section className="panel">
          <h2>Dernières commandes</h2>
          {mesCommandes.length === 0 ? (
            <p className="muted">Aucune commande pour le moment.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Numéro</th>
                    <th>Date</th>
                    <th>Statut</th>
                  </tr>
                </thead>
                <tbody>
                  {mesCommandes.map((commande) => (
                    <tr key={commande.id}>
                      <td>{commande.numero}</td>
                      <td>{new Date(commande.createdAt).toLocaleDateString('fr-FR')}</td>
                      <td><StatusBadge statut={commande.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </>
    );
  }

  return (
    <>
      <PageHeader
        title="Tableau de bord global"
        subtitle="Vue d'ensemble des magasins, commandes et stocks"
      />

      {error && <p className="error-text">{error}</p>}

      {dashboard && (
        <>
          <div className="stats-grid">
            <StatCard label="Magasins actifs" value={dashboard.stats.magasinsActifs} />
            <StatCard
              label="Commandes en attente"
              value={dashboard.stats.commandesEnAttente}
              alert={dashboard.stats.commandesEnAttente > 0}
            />
            <StatCard
              label="Alertes stock production"
              value={dashboard.stats.alertesStockProduction}
              alert={dashboard.stats.alertesStockProduction > 0}
            />
            <StatCard
              label="Alertes inventaire magasins"
              value={dashboard.stats.alertesInventaireMagasins}
              alert={dashboard.stats.alertesInventaireMagasins > 0}
            />
          </div>

          <div className="grid-2">
            <section className="panel">
              <h2>Commandes récentes</h2>
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr>
                      <th>Numéro</th>
                      <th>Magasin</th>
                      <th>Statut</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dashboard.commandesRecentes.map((commande) => (
                      <tr key={commande.id}>
                        <td>{commande.numero}</td>
                        <td>{commande.magasin?.nom}</td>
                        <td><StatusBadge statut={commande.statut} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section className="panel">
              <h2>Alertes</h2>
              <div className="alert-list">
                {dashboard.alertes.inventairesMagasins.slice(0, 5).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>{item.produit.nom}</strong>
                    <span>{item.magasin?.nom ?? 'Magasin'} — {item.quantite} restants</span>
                  </div>
                ))}
                {dashboard.alertes.stockProduits.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Stock production : {item.produit.nom}</strong>
                    <span>{item.quantite} {item.produit.unite}</span>
                  </div>
                ))}
                {dashboard.alertes.stockMarchandises.slice(0, 3).map((item) => (
                  <div key={item.id} className="alert-item">
                    <strong>Matière : {item.marchandise.nom}</strong>
                    <span>{item.quantite} {item.marchandise.unite}</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        </>
      )}
    </>
  );
}

import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { inventaireApi } from '../lib/api';
import { PageHeader } from '../components/UI';
import type { InventaireMagasin } from '../types';

export function InventairePage() {
  const { user } = useAuth();
  const [inventaires, setInventaires] = useState<InventaireMagasin[]>([]);
  const [error, setError] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);

  const magasinId = user?.magasinId;

  useEffect(() => {
    if (!magasinId) return;

    inventaireApi
      .list(magasinId)
      .then(setInventaires)
      .catch((err) => setError(err.message));
  }, [magasinId]);

  async function updateQuantite(produitId: string, quantite: number) {
    if (!magasinId) return;

    setSavingId(produitId);
    try {
      const updated = await inventaireApi.update(produitId, { magasinId, quantite });
      setInventaires((items) =>
        items.map((item) => (item.produitId === produitId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setSavingId(null);
    }
  }

  return (
    <>
      <PageHeader
        title="Inventaire du magasin"
        subtitle="Mettez à jour les quantités disponibles en boutique"
      />

      {error && <p className="error-text">{error}</p>}

      <section className="panel">
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Produit</th>
                <th>Catégorie</th>
                <th>Quantité</th>
                <th>Seuil d'alerte</th>
                <th>État</th>
              </tr>
            </thead>
            <tbody>
              {inventaires.map((item) => {
                const lowStock = item.quantite <= item.seuilAlerte;
                return (
                  <tr key={item.id} className={lowStock ? 'row-alert' : ''}>
                    <td>
                      <strong>{item.produit.nom}</strong>
                      <small>{item.produit.unite}</small>
                    </td>
                    <td>{item.produit.categorie}</td>
                    <td>
                      <input
                        type="number"
                        min="0"
                        step="1"
                        value={item.quantite}
                        onChange={(e) =>
                          updateQuantite(item.produitId, Number(e.target.value))
                        }
                        disabled={savingId === item.produitId}
                      />
                    </td>
                    <td>{item.seuilAlerte}</td>
                    <td>{lowStock ? '⚠️ Stock bas' : 'OK'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    </>
  );
}

import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { commandesApi } from '../lib/api';
import { PageHeader, StatusBadge } from '../components/UI';
import type { Commande, StatutCommande } from '../types';

const nextStatut: Partial<Record<StatutCommande, StatutCommande>> = {
  EN_ATTENTE: 'EN_PREPARATION',
  EN_PREPARATION: 'EXPEDIEE',
  EXPEDIEE: 'LIVREE',
};

export function CommandesPage() {
  const { user } = useAuth();
  const [commandes, setCommandes] = useState<Commande[]>([]);
  const [error, setError] = useState('');
  const [loadingId, setLoadingId] = useState<string | null>(null);

  useEffect(() => {
    commandesApi
      .list()
      .then(setCommandes)
      .catch((err) => setError(err.message));
  }, []);

  async function advanceStatut(commande: Commande) {
    const next = nextStatut[commande.statut];
    if (!next) return;

    setLoadingId(commande.id);
    try {
      const updated = await commandesApi.updateStatut(commande.id, next);
      setCommandes((items) => items.map((item) => (item.id === updated.id ? updated : item)));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setLoadingId(null);
    }
  }

  return (
    <>
      <PageHeader
        title={user?.role === 'MAGASIN' ? 'Mes commandes' : 'Commandes reçues'}
        subtitle={
          user?.role === 'PRODUCTION'
            ? 'Les commandes des magasins arrivent directement ici'
            : 'Suivi des commandes envoyées au centre de production'
        }
      />

      {error && <p className="error-text">{error}</p>}

      <section className="panel">
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Numéro</th>
                {user?.role !== 'MAGASIN' && <th>Magasin</th>}
                <th>Date</th>
                <th>Produits</th>
                <th>Statut</th>
                {user?.role !== 'MAGASIN' && <th>Action</th>}
              </tr>
            </thead>
            <tbody>
              {commandes.map((commande) => (
                <tr key={commande.id}>
                  <td><strong>{commande.numero}</strong></td>
                  {user?.role !== 'MAGASIN' && <td>{commande.magasin?.nom}</td>}
                  <td>{new Date(commande.createdAt).toLocaleString('fr-FR')}</td>
                  <td>
                    <ul className="inline-list">
                      {commande.lignes.map((ligne) => (
                        <li key={ligne.id}>
                          {ligne.quantite} × {ligne.produit.nom}
                        </li>
                      ))}
                    </ul>
                  </td>
                  <td><StatusBadge statut={commande.statut} /></td>
                  {user?.role !== 'MAGASIN' && (
                    <td>
                      {nextStatut[commande.statut] ? (
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          disabled={loadingId === commande.id}
                          onClick={() => advanceStatut(commande)}
                        >
                          → {nextStatut[commande.statut]}
                        </button>
                      ) : (
                        '—'
                      )}
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </>
  );
}

import { FormEvent, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { commandesApi, produitsApi } from '../lib/api';
import { PageHeader } from '../components/UI';
import type { Produit } from '../types';

export function NouvelleCommandePage() {
  const navigate = useNavigate();
  const [produits, setProduits] = useState<Produit[]>([]);
  const [quantites, setQuantites] = useState<Record<string, number>>({});
  const [notes, setNotes] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    produitsApi
      .list()
      .then(setProduits)
      .catch((err) => setError(err.message));
  }, []);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();

    const lignes = Object.entries(quantites)
      .filter(([, quantite]) => quantite > 0)
      .map(([produitId, quantite]) => ({ produitId, quantite }));

    if (lignes.length === 0) {
      setError('Ajoutez au moins un produit à la commande');
      return;
    }

    setLoading(true);
    setError('');

    try {
      await commandesApi.create({ lignes, notes: notes || undefined });
      navigate('/commandes');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <PageHeader
        title="Nouvelle commande"
        subtitle="Envoyée directement au centre de production"
      />

      {error && <p className="error-text">{error}</p>}

      <form onSubmit={handleSubmit} className="panel form-panel">
        <div className="product-order-grid">
          {produits.map((produit) => (
            <label key={produit.id} className="product-order-card">
              <div>
                <strong>{produit.nom}</strong>
                <span>{produit.categorie} — {produit.prix.toFixed(2)} €</span>
              </div>
              <input
                type="number"
                min="0"
                step="1"
                placeholder="0"
                value={quantites[produit.id] ?? ''}
                onChange={(e) =>
                  setQuantites((prev) => ({
                    ...prev,
                    [produit.id]: Number(e.target.value) || 0,
                  }))
                }
              />
            </label>
          ))}
        </div>

        <label>
          Notes pour la production
          <textarea
            rows={3}
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            placeholder="Ex : livraison demain matin à 6h"
          />
        </label>

        <button type="submit" className="btn btn-primary" disabled={loading}>
          {loading ? 'Envoi...' : 'Envoyer la commande'}
        </button>
      </form>
    </>
  );
}

