  useEffect(() => {
    stockApi
      .produits()
      .then(setStock)
      .catch((err) => setError(err.message));
  }, []);

  async function updateQuantite(produitId: string, quantite: number) {
    try {
      const updated = await stockApi.updateProduit(produitId, { quantite });
      setStock((items) => items.map((item) => (item.produitId === produitId ? updated : item)));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
