import { FormEvent, useEffect, useState } from 'react';
import { marchandisesApi, stockApi } from '../lib/api';
import { PageHeader } from '../components/UI';
import type { Marchandise, StockMarchandise } from '../types';

export function MarchandisesPage() {
  const [marchandises, setMarchandises] = useState<Marchandise[]>([]);
  const [stock, setStock] = useState<StockMarchandise[]>([]);
  const [nom, setNom] = useState('');
  const [categorie, setCategorie] = useState('');
  const [unite, setUnite] = useState('kg');
  const [quantite, setQuantite] = useState(0);
  const [error, setError] = useState('');

  async function load() {
    const [items, stockItems] = await Promise.all([
      marchandisesApi.list(),
      stockApi.marchandises(),
    ]);
    setMarchandises(items);
    setStock(stockItems);
  }

  useEffect(() => {
    load().catch((err) => setError(err.message));
  }, []);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    try {
      await marchandisesApi.create({ nom, categorie, unite, quantite });
      setNom('');
      setCategorie('');
      setUnite('kg');
      setQuantite(0);
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  async function updateQuantite(marchandiseId: string, value: number) {
    try {
      const updated = await stockApi.updateMarchandise(marchandiseId, { quantite: value });
      setStock((items) =>
        items.map((item) => (item.marchandiseId === marchandiseId ? updated : item)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur');
    }
  }

  return (
    <>
      <PageHeader
        title="Marchandises & matières premières"
        subtitle="Gestion du stock au centre de production"
      />

      {error && <p className="error-text">{error}</p>}

      <div className="grid-2">
        <section className="panel">
          <h2>Stock des marchandises</h2>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Nom</th>
                  <th>Catégorie</th>
                  <th>Quantité</th>
                  <th>Unité</th>
                </tr>
              </thead>
              <tbody>
                {stock.map((item) => (
                  <tr key={item.id}>
                    <td><strong>{item.marchandise.nom}</strong></td>
                    <td>{item.marchandise.categorie}</td>
                    <td>
                      <input
                        type="number"
                        min="0"
                        step="0.1"
                        value={item.quantite}
                        onChange={(e) =>
                          updateQuantite(item.marchandiseId, Number(e.target.value))
                        }
                      />
                    </td>
                    <td>{item.marchandise.unite}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <section className="panel form-panel">
          <h2>Créer une marchandise</h2>
          <form onSubmit={handleSubmit}>
            <label>
              Nom
              <input value={nom} onChange={(e) => setNom(e.target.value)} required />
            </label>
            <label>
              Catégorie
              <input value={categorie} onChange={(e) => setCategorie(e.target.value)} required />
            </label>
            <label>
              Unité
              <input value={unite} onChange={(e) => setUnite(e.target.value)} />
            </label>
            <label>
              Quantité initiale
              <input
                type="number"
                min="0"
                step="0.1"
                value={quantite}
                onChange={(e) => setQuantite(Number(e.target.value))}
              />
            </label>
            <button type="submit" className="btn btn-primary">Ajouter</button>
          </form>

          <div className="mini-list">
            <h3>Références actives</h3>
            <ul>
              {marchandises.map((item) => (
                <li key={item.id}>{item.nom} ({item.categorie})</li>
              ))}
            </ul>
          </div>
        </section>
      </div>
    </>
  );
}

import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { Layout } from './components/Layout';
import { ProtectedRoute } from './components/ProtectedRoute';
import { LoginPage } from './pages/LoginPage';
import { DashboardPage } from './pages/DashboardPage';
import { InventairePage } from './pages/InventairePage';
import { CommandesPage } from './pages/CommandesPage';
import { NouvelleCommandePage } from './pages/NouvelleCommandePage';
import { MagasinsPage } from './pages/MagasinsPage';
import { StockProductionPage } from './pages/StockProductionPage';
import { MarchandisesPage } from './pages/MarchandisesPage';

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <Routes>
          <Route path="/login" element={<LoginPage />} />

          <Route element={<ProtectedRoute />}>
            <Route element={<Layout />}>
              <Route index element={<DashboardPage />} />
              <Route path="commandes" element={<CommandesPage />} />

              <Route element={<ProtectedRoute roles={['MAGASIN']} />}>
                <Route path="inventaire" element={<InventairePage />} />
                <Route path="nouvelle-commande" element={<NouvelleCommandePage />} />
              </Route>

              <Route element={<ProtectedRoute roles={['ADMIN']} />}>
                <Route path="magasins" element={<MagasinsPage />} />
              </Route>

              <Route element={<ProtectedRoute roles={['ADMIN', 'PRODUCTION']} />}>
                <Route path="production/stock" element={<StockProductionPage />} />
                <Route path="production/marchandises" element={<MarchandisesPage />} />
              </Route>
            </Route>
          </Route>

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  );
}

