  background:
    radial-gradient(circle at top right, rgba(180, 83, 9, 0.15), transparent 30%),
    linear-gradient(180deg, #fff7ed, #f7f1e8);
}

.login-card {
  width: min(100%, 480px);
  background: white;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 2rem;
  box-shadow: var(--shadow);
}

.login-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.login-header h1 {
  margin: 0.5rem 0 0.25rem;
}

.login-header p,
.demo-accounts p,
.muted {
  color: var(--muted);
}

.demo-accounts {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
  font-size: 0.92rem;
}

.demo-accounts ul {
  padding-left: 1.1rem;
}

.error-text {
  color: var(--alert);
}

.loading-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
}

.product-order-grid {
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  margin-bottom: 1rem;
}

.product-order-card {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1rem;
  background: white;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.product-order-card span {
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 960px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: sticky;
    top: 0;
    z-index: 10;
  }

  .stats-grid,
  .grid-2 {
    grid-template-columns: 1fr;
  }
}

